  const maxConcurrent = rng.int(profile.concurrent.min, profile.concurrent.max);

  return {
    monsterType: monsterParams,
    packSize: totalToSpawn,
    maxConcurrent,
    cooldownTicks: profile.cooldown,
    depth: depth,
  };
}

