    if (room.isolated) return false;
    const isDeadEnd = countRoomEntrances(room, chunk) === 1;
    const hasStair = roomContainsStairTile(room, chunk);
    const isEntryRoom = !!entryRoom &&
      room.x === entryRoom.x &&
      room.y === entryRoom.y &&
      room.w === entryRoom.w &&
      room.h === entryRoom.h;
