                if (nx < 0 || ny < 0 || nx >= CHUNK_SIZE || ny >= CHUNK_SIZE) { nearWall = true; break; }
                if (chunk.tiles[ny * CHUNK_SIZE + nx] === TILE_WALL) { nearWall = true; break; }
